import{_ as a,a0 as l,w as r,s as d,ao as s,I as i,x as p,a1 as n,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"12個進程管理命令介紹 | LCTT x X-CMD","titleTemplate":false,"description":"12個進程管理命令介紹 | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"12個進程管理命令介紹 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"12個進程管理命令介紹 | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150326 A Peep into Process Management Commands in Linux","title":"12個進程管理命令介紹","tag":"201506","desc":""},"relativePath":"201506/20150326 A Peep into Process Management Commands in Linux.md","filePath":"[post].md"}'),c={name:"201506/20150326 A Peep into Process Management Commands in Linux.md"};function m(g,e,h,u,x,b){const t=l("Link");return r(),d("div",null,[e[13]||(e[13]=s(`<h1 id="_12個進程管理命令介紹" tabindex="-1">12個進程管理命令介紹 <a class="header-anchor" href="#_12個進程管理命令介紹" aria-label="Permalink to “12個進程管理命令介紹”">​</a></h1><p>執行中的程序在稱作進程。當程序以可執行文件存放在存儲中，並且運行的時候，每個進程會被動態得分配系統資源、內存、安全屬性和與之相關的狀態。可以有多個進程關聯到同一個程序，並同時執行不會互相干擾。操作系統會有效地管理和追蹤所有運行着的進程。</p><p>為了管理這些進程，用户應該能夠：</p><ul><li>查看所有運行中的進程</li><li>查看進程消耗資源</li><li>定位個別進程並且對其執行指定操作</li><li>改變進程的優先級</li><li>殺死指定進程</li><li>限制進程可用的系統資源等</li></ul><p>Linux提供了許多命令來讓用户來高效掌控上述的操作。接下來，一個一個的來講解下。</p><h3 id="_1-ps" tabindex="-1">1. ps <a class="header-anchor" href="#_1-ps" aria-label="Permalink to “1. ps”">​</a></h3><p>&#39;ps&#39;是Linux 中最基礎的瀏覽系統中的進程的命令。能列出系統中運行的進程，包括進程號、命令、CPU使用量、內存使用量等。下述選項可以得到更多有用的消息。</p><pre><code>ps -a - 列出所有運行中/激活進程
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/02/ps-a2.png" alt="Output of &quot;ps -a&quot; command"></p><pre><code>ps -ef |grep - 列出需要進程
ps -aux - 顯示進程信息，包括無終端的（x）和針對用户（u）的進程：如USER, PID, %CPU, %MEM等
</code></pre><h3 id="_2-pstree" tabindex="-1">2. pstree <a class="header-anchor" href="#_2-pstree" aria-label="Permalink to “2. pstree”">​</a></h3><p>linux中，每一個進程都是由其父進程創建的。此命令以可視化方式顯示進程，通過顯示進程的樹狀圖來展示進程間關係。如果指定了pid了，那麼樹的根是該pid，不然將會是init（pid： 1）。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/02/pstree.png" alt="pstree"></p><h3 id="_3-top" tabindex="-1">3. top <a class="header-anchor" href="#_3-top" aria-label="Permalink to “3. top”">​</a></h3><p>‘top’是一個更加有用的命令，可以監視系統中不同的進程所使用的資源。它提供實時的系統狀態信息。顯示進程的數據包括 PID、進程屬主、優先級、%CPU、%memory等。可以使用這些顯示指示出資源使用量。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/02/top.png" alt="top"></p><h3 id="_4-htop" tabindex="-1">4. htop <a class="header-anchor" href="#_4-htop" aria-label="Permalink to “4. htop”">​</a></h3><p>htop與top很類似，但是htop是交互式的文本模式的進程查看器。它通過文字圖形化地顯示每一個進程的CPU和內存使用量、swap使用量。使用上下光標鍵選擇進程，F7和F8改變優先級，F9殺死進程。Htop不是系統默認安裝的，所以需要額外安裝。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/htop1.png" alt="htop output"></p><h3 id="_5-nice" tabindex="-1">5. nice <a class="header-anchor" href="#_5-nice" aria-label="Permalink to “5. nice”">​</a></h3><p>通過nice命令的幫助，用户可以設置和改變進程的優先級。提高一個進程的優先級，內核會分配更多CPU時間片給這個進程。默認情況下，進程以0的優先級啓動。進程優先級可以通過top命令顯示的NI（nice value）列查看。</p><p>進程優先級值的範圍從-20到19。值越低，優先級越高。</p><pre><code>nice &lt;優先值&gt; &lt;進程名&gt; - 通過給定的優先值啓動一個程序
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/02/nice-cmd.png" alt="nice command"></p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/02/top-nice.png" alt="changed nice value of &#39;top&#39;"></p><p>上述命令例子中，可以看到‘top’命令獲得了-3的優先值。</p><h3 id="_6-renice" tabindex="-1">6. renice <a class="header-anchor" href="#_6-renice" aria-label="Permalink to “6. renice”">​</a></h3><p>renice命令類似nice命令。使用這個命令可以改變正在運行的進程優先值。注意，用户只能改變屬於他們自己的進程的優先值。</p><pre><code>renice -n -p - 改變指定進程的優先值
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/02/renice2.png" alt="renice command"></p><p>初始優先值為0的3806號進程優先值已經變成了4.</p><pre><code>renice -u -g - 通過指定用户和組來改變進程優先值
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/02/renice1.png" alt="output of renice for a user group"></p><p>上述例子中，用户為‘mint’的所有進程優先值變為‘-3’。</p><h3 id="_7-kill" tabindex="-1">7. kill <a class="header-anchor" href="#_7-kill" aria-label="Permalink to “7. kill”">​</a></h3><p>這個命令用於發送信號來結束進程。如果一個進程沒有響應殺死命令，這也許就需要強制殺死，使用-9參數來執行。注意，使用強制殺死的時候一定要小心，因為進程沒有時機清理現場，也許寫入文件沒有完成。如果我們不知道進程PID或者打算用名字殺死進程時候，killall就能派上用場。</p><pre><code>kill &lt;pid&gt;

kill -9 &lt;pid&gt;

killall -9 - 殺死所有擁有同樣名字的進程
</code></pre><p>如果你使用kill，你需要知道進程ID號。pkill是類似的命令，但使用模式匹配，如進程名，進程擁有者等。</p><pre><code>pkill &lt;進程名&gt;
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/02/kill-initiated.png" alt="kill initiated"></p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/02/kill.png" alt="kill"></p><h3 id="_8-ulimit" tabindex="-1">8. ulimit <a class="header-anchor" href="#_8-ulimit" aria-label="Permalink to “8. ulimit”">​</a></h3><p>該命令用於控制系統資源在shell和進程上的分配量。對於系統管理員是最有用的，可以管理重度使用和存在性能問題的系統。限制資源大小可以確保重要進程持續運行，其他進程不會佔用過多資源。</p><pre><code>ulimit -a - 顯示當前用户關聯的資源限制
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/02/ulimit-a.png" alt="ulimit -a"></p><pre><code>-f - 最大文件尺寸大小

-v - 最大虛擬內存大小（KB）

-n - 增加最大文件描述符數量

-H : 改變和報告硬限制

-S : 改變和報告軟限制
</code></pre><p>瀏覽ulimit man頁面獲取更多選項。</p><h3 id="_9-w" tabindex="-1">9. w <a class="header-anchor" href="#_9-w" aria-label="Permalink to “9. w”">​</a></h3><p>w 提供當前登錄的用户及其正在執行的進程的信息。顯示信息頭包含信息，如當前時間、系統運行時長、登錄用户總數、過去的1，5，15分鐘內的負載均衡數。</p><p>基於這些用户信息，用户在終止不屬於他們的進程時要小心。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/02/w.png" alt="&#39;w&#39; command"></p><p><strong>who</strong>是類似命令，提供當前登錄用户列表、系統啓動時間、運行級別等。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/02/who.png" alt="&#39;who&#39; command"></p><p><strong>whoami</strong> 命令輸出當前用户ID</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/02/whoami.png" alt="&#39;whoami&#39; command"></p><h3 id="_10-pgrep" tabindex="-1">10. pgrep <a class="header-anchor" href="#_10-pgrep" aria-label="Permalink to “10. pgrep”">​</a></h3><p>pgrep的意思是&quot;進程號全局正則匹配輸出&quot;。該命令掃描當前運行進程，然後按照命令匹配條件列出匹配結果到標準輸出。對於通過名字檢索進程號是很有用。</p><pre><code>pgrep -u mint sh
</code></pre><p>這個命令將會顯示用户為‘mint’和進程名為‘sh’的進程ID。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/pgrep.png" alt="output of pgrep"></p><h3 id="_11-fg-bg" tabindex="-1">11. fg , bg <a class="header-anchor" href="#_11-fg-bg" aria-label="Permalink to “11. fg , bg”">​</a></h3><p>有時，命令需要很長的時間才能執行完成。對於這種情況，我們使用‘bg’命令可以將任務放在後台執行，而用‘fg’可以調到前台來使用。</p><p>我們可以通過‘&amp;’在後台啓動一個程序:</p><pre><code>find . -name *iso &gt; /tmp/res.txt &amp;
</code></pre><p>一個正在運行的程序也可以通過“CTRL+Z”和“bg”命令組合放到後台運行。</p><pre><code>find . -name *iso &gt; /tmp/res.txt &amp;     -  啓動一個程序

ctrl+z      -   掛起當前執行程序

bg   -  將程序放到後台運行
</code></pre><p>我們可以使用‘jobs’命令列出所有後台進程。</p><pre><code>jobs
</code></pre><p>使用‘fg’命令可以將後台程序調到前台執行。</p><pre><code>fg %進程id
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/fg-bg-jobs.png" alt="output of fg, bg and jobscommands"></p><h3 id="_12-ipcs" tabindex="-1">12. ipcs <a class="header-anchor" href="#_12-ipcs" aria-label="Permalink to “12. ipcs”">​</a></h3><p>ipcs命令報告進程間通信設施狀態。（共享內存，信號量和消息隊列）</p><p>用-p參數聯合-m、-s或-q使用，可以獲得相關的進程間通信的進程ID。</p><pre><code>ipcs -p -m
</code></pre><p>下面屏幕截圖列出了最近訪問了共享內存段的進程的創建者的ID和進程ID。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/ipcs.png" alt="ipcs command"></p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>總之 ，這些命令可以幫助管理員修復問題和改善性能。同樣作為一名普通用户也需要解決進程出現的問題。所以，熟悉如此繁多的命令，從能有效管理進程是行之有效。</p><hr>`,80)),i("p",null,[e[1]||(e[1]=p("via: ",-1)),n(t,{href:"http://linoxide.com/linux-command/process-management-commands-linux/"},{default:o(()=>[...e[0]||(e[0]=[p("http://linoxide.com/linux-command/process-management-commands-linux/",-1)])]),_:1})]),i("p",null,[e[5]||(e[5]=p("作者：",-1)),n(t,{href:"http://linoxide.com/author/bnpoornima/"},{default:o(()=>[...e[2]||(e[2]=[p("B N Poornima",-1)])]),_:1}),e[6]||(e[6]=p(" 譯者：",-1)),n(t,{href:"http://vicyu.net"},{default:o(()=>[...e[3]||(e[3]=[p("VicYu/Vic020",-1)])]),_:1}),e[7]||(e[7]=p(" 校對：",-1)),n(t,{href:"https://github.com/wxy"},{default:o(()=>[...e[4]||(e[4]=[p("wxy",-1)])]),_:1})]),i("p",null,[e[10]||(e[10]=p("本文由 ",-1)),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[8]||(e[8]=[p("LCTT",-1)])]),_:1}),e[11]||(e[11]=p(" 原創翻譯，",-1)),n(t,{href:"http://linux.cn/"},{default:o(()=>[...e[9]||(e[9]=[p("Linux中國",-1)])]),_:1}),e[12]||(e[12]=p(" 榮譽推出",-1))])])}const w=a(c,[["render",m]]);export{P as __pageData,w as default};
